--- index.html
+++ index.html
@@ -48,9 +48,9 @@
 function setCounts(){document.querySelector('#seedCount').textContent=seedCount;document.querySelector('#treeCount').textContent=`${planted} / 8`}
 function start(){document.querySelector('#intro').classList.add('hidden');running=true;last=performance.now();audioPing(520)}
 document.querySelector('#startBtn').onclick=start;
 document.querySelector('#againBtn').onclick=()=>{location.reload()};
-function doPlant(){if(!running||won)return;let site=sites.find(s=>!s.planted&&Math.hypot(player.x-s.x,player.y-s.y)<62);if(site&&seedCount>0){site.planted=true;seedCount--;planted++;for(let i=0;i<28;i++)particles.push({x:site.x,y:site.y,vx:(rand()-.5)*95,vy:-25-rand()*90,life:.8+rand()*.7,color:i%2?'#e7d18a':'#a8c987'});setCounts();audioPing(740);if(planted===8){won=true;setTimeout(()=>document.querySelector('#finish').classList.remove('hidden'),700)}}}
+function doPlant(){if(!running||won)return;let site=sites.find(s=>!s.planted&&Math.hypot(player.x-s.x,player.y-s.y)<62);if(site&&seedCount>0){site.planted=true;site.plantedAt=performance.now();seedCount--;planted++;for(let i=0;i<28;i++)particles.push({x:site.x,y:site.y,vx:(rand()-.5)*95,vy:-25-rand()*90,life:.8+rand()*.7,color:i%2?'#e7d18a':'#a8c987'});setCounts();audioPing(740);if(planted===8){won=true;setTimeout(()=>document.querySelector('#finish').classList.remove('hidden'),700)}}}
 addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='e'||k===' ')doPlant();if(k==='enter'&&!running)start()},{passive:false});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
 document.querySelector('#touchPlant').addEventListener('pointerdown',e=>{e.preventDefault();doPlant()});
 document.querySelectorAll('[data-dir]').forEach(b=>{let k={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;b.setPointerCapture(e.pointerId)});for(let ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys[k]=false)});
 document.querySelector('#soundBtn').onclick=()=>{soundOn=!soundOn;document.querySelector('#soundBtn').textContent=soundOn?'♫':'♪';if(soundOn)audioPing(660)};
